/*
 * Resample from 8 / 16 / 32 KHz to 12.8 KHz, HiFi4 4-lane int16 MAC.
 *
 * Replaces the scalar `un += xn[k] * hn[k]` accumulation in
 * resample_x64k_12k8() with AE_MULAAAAQ16 4-lane multiply-accumulate.
 *
 * Bit-exactness contract with the scalar reference:
 *  - The scalar reference accumulates `int16 * int16` products into an
 *    `int32_t un`. Each Q15*Q15 product fits in Q30 (< 2^31), and the
 *    reference assumes the w-tap sum stays within int32 range (otherwise
 *    the reference itself is UB). The SIMD path accumulates into the 64-bit
 *    AE accumulator and narrows back to int32 before filter_hp50(), which is
 *    bit-identical whenever the reference does not overflow int32.
 *  - filter_hp50() is a cross-sample biquad (stateful, recursive) and is kept
 *    scalar; only the FIR tap accumulation is vectorized.
 *  - Output `(yn + (1 << 15)) >> 16` Q14 rounding is unchanged.
 */
static inline void xtensa_resample_x64k_12k8(const int p,
    const int16_t *h, struct lc3_ltpf_hp50_state *hp50,
    const int16_t *x, int16_t *y, int n)
{
    const int w = 2*(40 / p);

    x -= w - 1;

    for (int i = 0; i < 5*n; i += 5) {
        const int16_t *hn = h + (i % p) * w;
        const int16_t *xn = x + (i / p);

        const ae_int16x4 *pa = (const ae_int16x4 *)xn;
        const ae_int16x4 *pb = (const ae_int16x4 *)hn;
        ae_int64 sum = 0;
        ae_valign align_a = AE_LA64_PP(pa);
        ae_valign align_b = AE_LA64_PP(pb);

        int k = 0;
        for (; k + 4 <= w; k += 4) {
            ae_int16x4 va, vb;
            AE_LA16X4_IP(va, align_a, pa);
            AE_LA16X4_IP(vb, align_b, pb);
            AE_MULAAAAQ16(sum, va, vb);
        }

        int64_t v = (int64_t)sum;
        for (; k < w; k++)
            v += (int32_t)xn[k] * hn[k];

        int32_t yn = filter_hp50(hp50, (int32_t)v);
        *(y++) = (yn + (1 << 15)) >> 16;
    }
}

static inline void xtensa_resample_16k_12k8(
    struct lc3_ltpf_hp50_state *hp50, const int16_t *x, int16_t *y, int n)
{
    extern const int16_t h_16k_12k8_q15[4*20];
    xtensa_resample_x64k_12k8(4, h_16k_12k8_q15, hp50, x, y, n);
}

