/* ---- resample FIR bit-exactness ---- */

static int64_t scalar_resample_fir(
    const int16_t *xn, const int16_t *hn, int w)
{
    int32_t un = 0;
    for (int k = 0; k < w; k++)
        un += (int32_t)xn[k] * hn[k];
    return (int64_t)un;
}

static int firs_equal(
    const int16_t *xn, const int16_t *hn, int w)
{
    return xtensa_resample_fir(xn, hn, w) == scalar_resample_fir(xn, hn, w);
}

/* w=20 (16 KHz, p=4) is the production path; also exercise w=10 (p=8) and
 * w=40 (p=2) to cover the non-multiple-of-4 tail and the aligned body. */
static int resample_fir_equal_for_width(int w)
{
    _Alignas(8) int16_t xn[80];
    _Alignas(8) int16_t hn[80];
    uint32_t state = 0x5a5a5a5au;

    /* INT16_MAX fill */
    for (int i = 0; i < 80; i++) { xn[i] = INT16_MAX; hn[i] = INT16_MAX; }
    for (int off = 0; off < 2; off++)
        if (!firs_equal(xn + off, hn, w)) return 0;

    /* INT16_MIN fill */
    for (int i = 0; i < 80; i++) { xn[i] = INT16_MIN; hn[i] = INT16_MIN; }
    for (int off = 0; off < 2; off++)
        if (!firs_equal(xn + off, hn, w)) return 0;

    /* alternating sign */
    for (int i = 0; i < 80; i++) {
        xn[i] = (i & 1) ? INT16_MIN : INT16_MAX;
        hn[i] = (i & 1) ? INT16_MAX : INT16_MIN;
    }
    for (int off = 0; off < 2; off++)
        if (!firs_equal(xn + off, hn, w)) return 0;

    /* pseudo-random data + multiple offsets and widths */
    for (int i = 0; i < 80; i++) {
        xn[i] = (int16_t)(random_next(&state) >> 16);
        hn[i] = (int16_t)(random_next(&state) >> 16);
    }
    for (int off = 0; off <= 4; off++)
        if (!firs_equal(xn + off, hn + off, w)) return 0;

    /* single-tap rounding boundaries (mirrors dot boundary test) */
    static const int16_t boundary[] = {
        31, 32, 63, 64, 95, 96,
        -31, -32, -33, -63, -64, -65, -95, -96, -97
    };
    for (unsigned int i = 0; i < sizeof(boundary) / sizeof(boundary[0]); i++) {
        for (int k = 0; k < w; k++) xn[k] = hn[k] = 0;
        xn[0] = 1; hn[0] = boundary[i];
        if (!firs_equal(xn, hn, w)) return 0;
    }

    return 1;
}

