457	/**
458	 * Quantization of codebooks residual
459	 * scf             Input 16 scale factors, output quantized version
460	 * lf/hfcb_idx     Codebooks index
461	 * c, cn           Output 4 pulse configurations candidates, normalized
462	 * shape/gain_idx  Output selected shape/gain indexes
463	 */
464	LC3_HOT static void quantize(const float *scf, int lfcb_idx, int hfcb_idx,
465	    int (*c)[16], float (*cn)[16], int *shape_idx, int *gain_idx)
466	{
467	    /* --- Residual --- */
468	
469	    const float *lfcb = lc3_sns_lfcb[lfcb_idx];
470	    const float *hfcb = lc3_sns_hfcb[hfcb_idx];
471	    float r[16], x[16];
472	
473	    for (int i = 0; i < 8; i++) {
474	        r[  i] = scf[  i] - lfcb[i];
475	        r[8+i] = scf[8+i] - hfcb[i];
476	    }
477	
478	    dct16_forward(r, x);
479	
480	    /* --- Shape 3 candidate ---
481	     * Project to or below pyramid N = 16, K = 6,
482	     * then add unit pulses until you reach K = 6, over N = 16 */
483	
484	    float xm[16];
485	    float xm_sum = 0;
486	
487	    for (int i = 0; i < 16; i++) {
488	        xm[i] = fabsf(x[i]);
489	        xm_sum += xm[i];
490	    }
491	
492	    float proj_factor = (6 - 1) / fmaxf(xm_sum, 1e-31f);
493	    float corr = 0, energy = 0;
494	    int npulses = 0;
495	
496	    for (int i = 0; i < 16; i++) {
497	        c[3][i] = floorf(xm[i] * proj_factor);
498	        npulses += c[3][i];
499	        corr    += c[3][i] * xm[i];
500	        energy  += c[3][i] * c[3][i];
501	    }
502	
503	    add_pulse(xm, c[3], 16, npulses, 6, &corr, &energy);
504	    npulses = 6;
505	
506	    /* --- Shape 2 candidate ---
507	     * Add unit pulses until you reach K = 8 on shape 3 */
508	
509	    memcpy(c[2], c[3], sizeof(c[2]));
510	
511	    add_pulse(xm, c[2], 16, npulses, 8, &corr, &energy);
512	    npulses = 8;
513	
514	    /* --- Shape 1 candidate ---
515	     * Remove any unit pulses from shape 2 that are not part of 0 to 9
516	     * Update energy and correlation terms accordingly
517	     * Add unit pulses until you reach K = 10, over N = 10 */
518	
519	    memcpy(c[1], c[2], sizeof(c[1]));
520	
521	    for (int i = 10; i < 16; i++) {
522	        c[1][i] = 0;
523	        npulses -= c[2][i];
524	        corr    -= c[2][i] * xm[i];
525	        energy  -= c[2][i] * c[2][i];
526	    }
527	
528	    add_pulse(xm, c[1], 10, npulses, 10, &corr, &energy);
529	    npulses = 10;
530	
531	    /* --- Shape 0 candidate ---
532	     * Add unit pulses until you reach K = 1, on shape 1 */
533	
534	    memcpy(c[0], c[1], sizeof(c[0]));
535	
536	    add_pulse(xm + 10, c[0] + 10, 6, 0, 1, &corr, &energy);
537	
538	    /* --- Add sign and unit energy normalize --- */
539	
540	    for (int j = 0; j < 16; j++)
541	        for (int i = 0; i < 4; i++)
542	            c[i][j] = x[j] < 0 ? -c[i][j] : c[i][j];
543	
544	    for (int i = 0; i < 4; i++)
545	        normalize(c[i], cn[i]);
546	
547	    /* --- Determe shape & gain index ---
548	     * Search the Mean Square Error, within (shape, gain) combinations */
549	
550	    float mse_min = FLT_MAX;
551	    *shape_idx = *gain_idx = 0;
552	
553	    for (int ic = 0; ic < 4; ic++) {
554	        const struct lc3_sns_vq_gains *cgains = lc3_sns_vq_gains + ic;
555	        float cmse_min = FLT_MAX;
556	        int cgain_idx = 0;
557	
558	        for (int ig = 0; ig < cgains->count; ig++) {
559	            float g = cgains->v[ig];
560	
561	            float mse = 0;
562	            for (int i = 0; i < 16; i++)
563	                mse += (x[i] - g * cn[ic][i]) * (x[i] - g * cn[ic][i]);
564	
565	            if (mse < cmse_min) {
566	                cgain_idx = ig,
567	                cmse_min = mse;
568	            }
569	        }
570	
571	        if (cmse_min < mse_min) {
572	            *shape_idx = ic, *gain_idx = cgain_idx;
573	            mse_min = cmse_min;
574	        }
575	    }
576	}
