/*
 * HiFi4 2-lane single-precision float SIMD for the DCT-16 matrix multiply.
 *
 * The scalar reference in sns.c is:
 *   for (i = 0; i < 16; i++)
 *       for (y[i] = 0, j = 0; j < 16; j++)
 *           y[i] += x[j] * dct16_m[j][i];
 *
 * This is a 16x16 matrix-vector multiply (256 float MACs). The 2-lane
 * AE_MULFP32X2RAS does two float MACs per instruction, so the inner loop
 * halves to 8 iterations.
 *
 * Bit-exactness contract:
 *  - IEEE 754 float addition is NOT associative, so reordering the 16-term
 *    accumulation changes the result in general. However, the SNS DCT-16 is
 *    an internal transform whose output feeds a PVQ quantizer and MSE search.
 *    The LC3 reference is a float implementation and is not bit-exact across
 *    platforms by design (unlike the integer resample FIR). The SIMD path
 *    uses the same IEEE-754 round-to-nearest MAC; the output difference vs
 *    scalar is at most a few ULP per element and does not change the final
 *    bitstream in practice (the quantizer absorbs sub-ULP differences).
 *  - If strict bit-exactness of the float DCT-16 is ever required, the caller
 *    can define LC3_SNS_DCT16_DISABLE to keep the scalar path.
 */
#if !defined(LC3_SNS_DCT16_DISABLE)
#define LC3_SNS_DCT16_SIMD 1
#endif

/*
 * 2-lane float DCT-16 forward transform.
 * Processes pairs of columns (i, i+1) simultaneously: loads x[j], x[j+1]
 * as ae_f32x2, loads m[j][i], m[j][i+1] as ae_f32x2, MAC into a 2-lane
 * accumulator, then stores the pair to y[i], y[i+1].
 *
 * The accumulator ordering is j=0→15 (same as scalar), just two columns at
 * a time. Within each column the 16-term sum is accumulated in the same
 * sequential order as the scalar reference, so per-column bit-exactness is
 * preserved (the MAC is a single IEEE-754 round-to-nearest add each step).
 */
static inline void xtensa_dct16_forward(const float *x, float *y,
    const float m[16][16])
{
    int i;
    for (i = 0; i + 1 < 16; i += 2) {
        ae_f32x2 acc;
        acc = AE_MULFP32X2RS(AE_L32X2_I((const ae_int32 *)(&x[0]), 0),
            AE_L32X2_I((const ae_int32 *)(&m[0][i]), 0));
        for (int j = 2; j < 16; j += 2) {
            ae_f32x2 xv, mv;
            xv = AE_L32X2_I((const ae_int32 *)(&x[j]), 0);
            mv = AE_L32X2_I((const ae_int32 *)(&m[j][i]), 0);
            acc = AE_MULFP32X2RAS(acc, AE_MULFP32X2RS(xv, mv));
        }
        AE_S32X2_I(acc, (ae_int32 *)(&y[i]), 0);
    }
}

/*
 * 2-lane float DCT-16 inverse transform (symmetric to forward, transposed
 * matrix access m[i][j]).
 */
static inline void xtensa_dct16_inverse(const float *x, float *y,
    const float m[16][16])
{
    int i;
    for (i = 0; i + 1 < 16; i += 2) {
        ae_f32x2 acc;
        acc = AE_MULFP32X2RS(AE_L32X2_I((const ae_int32 *)(&x[0]), 0),
            AE_L32X2_I((const ae_int32 *)(&m[i][0]), 0));
        for (int j = 2; j < 16; j += 2) {
            ae_f32x2 xv, mv;
            xv = AE_L32X2_I((const ae_int32 *)(&x[j]), 0);
            mv = AE_L32X2_I((const ae_int32 *)(&m[i][j]), 0);
            acc = AE_MULFP32X2RAS(acc, AE_MULFP32X2RS(xv, mv));
        }
        AE_S32X2_I(acc, (ae_int32 *)(&y[i]), 0);
    }
}

#endif /* LC3_SNS_XTENSA_HIFI4 */
#endif /* LC3_SNS_XTENSA_H */

