#ifndef LC3_SNS_XTENSA_H
#define LC3_SNS_XTENSA_H

#include <stdint.h>

#if defined(TEST_XTENSA_HIFI4)
#define LC3_SNS_XTENSA_HIFI4
#elif defined(CONFIG_LIB_LC3_XTENSA_HIFI4) && defined(__XTENSA__)
#include <xtensa/config/core-isa.h>
#if XCHAL_HAVE_HIFI4
#include <xtensa/tie/xt_hifi2.h>
#define LC3_SNS_XTENSA_HIFI4
#endif
#endif

/*
 * HiFi4 2-lane single-precision float SIMD for the SNS DCT-16 transforms.
 *
 * The scalar reference in sns.c:
 *   for (i = 0; i < 16; i++)
 *       for (y[i] = 0, j = 0; j < 16; j++)
 *           y[i] += x[j] * m[j][i];   // forward: m[j][i]
 *           y[i] += x[j] * m[i][j];   // inverse: m[i][j]
 *
 * Each y[i] is a 16-term dot product.  The HiFi4 AE_F32X2_MULF_F32X2 /
 * AE_F32X2_ADDS_F32X2 pair does two float multiply-adds per 2-lane op,
 * halving the MAC count.
 *
 * Bit-exactness contract:
 *  - IEEE 754 float addition is NOT associative; reordering a 16-term sum
 *    changes the result by sub-ULP in general.  The SIMD path below keeps
 *    the SAME left-to-right accumulation order per output lane — it loads
 *    two consecutive x values (j, j+1), multiplies each by its coefficient,
 *    and adds them to the accumulator in j-ascending order.  Because each
 *    AE_F32X2_ADDS_F32X2 is a single IEEE-754 round-to-nearest add per lane
 *    and the lanes are independent, the per-lane accumulation sequence is
 *    identical to the scalar loop.  The only reorder is that two adjacent
 *    products are computed in parallel before being summed — but the sum
 *    order (which determines the rounding sequence) is preserved.
 *  - If strict bit-exactness of the float DCT-16 output is ever required
 *    regardless, define LC3_SNS_DCT16_DISABLE to keep the scalar path.
 */
#if defined(LC3_SNS_XTENSA_HIFI4)

#if !defined(LC3_SNS_DCT16_DISABLE)
#define LC3_SNS_DCT16_SIMD 1

/*
 * 2-lane float DCT-16 forward transform.
 * Processes pairs of output columns (i, i+1):
 *   lane0 accumulates y[i]     = sum_j x[j] * m[j][i]
 *   lane1 accumulates y[i+1]   = sum_j x[j] * m[j][i+1]
 * For each j step we load x[j] (broadcast to both lanes via pair load of
 * m[j][i] and m[j][i+1] which already lives in adjacent memory), multiply,
 * and add.  The accumulation order j=0..15 is preserved per lane.
 */
static inline void xtensa_dct16_forward(const float *x, float *y,
    const float m[16][16])
{
    int i;
    for (i = 0; i + 1 < 16; i += 2) {
        ae_f32x2 acc;
        int j;

        /* j = 0: acc = x[0] * (m[0][i], m[0][i+1]) */
        ae_f32x2 mv = AE_LF32X2_I(&m[0][i], 0);
        float xj0 = x[0];
        ae_f32x2 xv = { xj0, xj0 };
        acc = AE_F32X2_MULF_F32X2(xv, mv);

        for (j = 1; j < 16; j++) {
            mv = AE_LF32X2_I(&m[j][i], 0);
            float xj = x[j];
            ae_f32x2 xv2 = { xj, xj };
            ae_f32x2 prod = AE_F32X2_MULF_F32X2(xv2, mv);
            acc = AE_F32X2_ADDS_F32X2(acc, prod);
        }
        AE_SF32X2_I(acc, &y[i], 0);
    }
}

/*
 * 2-lane float DCT-16 inverse transform (m[i][j] access instead of m[j][i]).
 */
static inline void xtensa_dct16_inverse(const float *x, float *y,
    const float m[16][16])
{
    int i;
    for (i = 0; i + 1 < 16; i += 2) {
        ae_f32x2 acc;
        int j;

        ae_f32x2 mv = AE_LF32X2_I(&m[i][0], 0);
        float xj0 = x[0];
        ae_f32x2 xv = { xj0, xj0 };
        acc = AE_F32X2_MULF_F32X2(xv, mv);

        for (j = 1; j < 16; j++) {
            mv = AE_LF32X2_I(&m[i][j], 0);
            float xj = x[j];
            ae_f32x2 xv2 = { xj, xj };
            ae_f32x2 prod = AE_F32X2_MULF_F32X2(xv2, mv);
            acc = AE_F32X2_ADDS_F32X2(acc, prod);
        }
        AE_SF32X2_I(acc, &y[i], 0);
    }
}

#endif /* LC3_SNS_DCT16_DISABLE */
#endif /* LC3_SNS_XTENSA_HIFI4 */
