/* ---- scalar reference (mirrors sns.c) ---- */

static void scalar_dct16_forward(const float *x, float *y,
    const float m[16][16])
{
    for (int i = 0, j; i < 16; i++)
        for (y[i] = 0, j = 0; j < 16; j++)
            y[i] += x[j] * m[j][i];
}

static void scalar_dct16_inverse(const float *x, float *y,
    const float m[16][16])
{
    for (int i = 0, j; i < 16; i++)
        for (y[i] = 0, j = 0; j < 16; j++)
            y[i] += x[j] * m[i][j];
}

/* ---- bit-exact comparison ---- */

static int f32_bits_equal(float a, float b)
{
    uint32_t ua, ub;
    memcpy(&ua, &a, 4);
    memcpy(&ub, &b, 4);
    return ua == ub;
}

static uint32_t random_next(uint32_t *state)
{
    *state = *state * 1664525u + 1013904223u;
    return *state;
}

static float random_float(uint32_t *state)
{
    /* generate float in [-1, 1] with full mantissa coverage */
    uint32_t u = random_next(state);
    /* clear sign, set exponent to 0 (subnormal-like range) then scale */
    uint32_t bits = (u & 0x807fffff) | 0x3f000000; /* [0.5, 1) */
    float f;
    memcpy(&f, &bits, 4);
    return (u & 0x80000000) ? -f : f;
}

static int dct16_forward_equal(const float *x, const float m[16][16])
{
    float y_scalar[16], y_simd[16];
    scalar_dct16_forward(x, y_scalar, m);
    xtensa_dct16_forward(x, y_simd, m);
    for (int i = 0; i < 16; i++)
        if (!f32_bits_equal(y_scalar[i], y_simd[i]))
            return 0;
    return 1;
}

static int dct16_inverse_equal(const float *x, const float m[16][16])
{
    float y_scalar[16], y_simd[16];
    scalar_dct16_inverse(x, y_scalar, m);
    xtensa_dct16_inverse(x, y_simd, m);
    for (int i = 0; i < 16; i++)
        if (!f32_bits_equal(y_scalar[i], y_simd[i]))
            return 0;
    return 1;
}

int check_sns_xtensa(void)
{
    _Alignas(8) float m[16][16];
    _Alignas(8) float x[16];
    uint32_t state = 0x5a5a5a5au;

    /* test 1: identity-ish matrix (m[i][j] = delta) — accumulation of single
     * nonzero term, trivially exact */
    for (int i = 0; i < 16; i++)
        for (int j = 0; j < 16; j++)
            m[i][j] = (i == j) ? 1.0f : 0.0f;
    for (int i = 0; i < 16; i++)
        x[i] = (float)(i + 1) * 0.5f;
    if (!dct16_forward_equal(x, m))
        return -1;
    if (!dct16_inverse_equal(x, m))
        return -2;

    /* test 2: all-ones matrix — sum of 16 identical products */
    for (int i = 0; i < 16; i++)
        for (int j = 0; j < 16; j++)
            m[i][j] = 1.0f;
    for (int i = 0; i < 16; i++)
        x[i] = 0.0625f;
    if (!dct16_forward_equal(x, m))
        return -3;
    if (!dct16_inverse_equal(x, m))
        return -4;

    /* test 3: pseudo-random data — stress sub-ULP accumulation differences */
    for (int iter = 0; iter < 1000; iter++) {
        for (int i = 0; i < 16; i++)
            for (int j = 0; j < 16; j++)
                m[i][j] = random_float(&state);
        for (int i = 0; i < 16; i++)
            x[i] = random_float(&state);
        if (!dct16_forward_equal(x, m))
            return -5;
        if (!dct16_inverse_equal(x, m))
            return -6;
    }

    /* test 4: large dynamic range — values that produce very different
     * magnitudes in the accumulation (cancellation) */
    for (int i = 0; i < 16; i++)
        for (int j = 0; j < 16; j++)
            m[i][j] = random_float(&state);
    for (int i = 0; i < 16; i++)
        x[i] = (i & 1) ? 1e6f : -1e6f;
    if (!dct16_forward_equal(x, m))
        return -7;
    if (!dct16_inverse_equal(x, m))
        return -8;

    /* test 5: very small values (subnormal-adjacent) */
    for (int i = 0; i < 16; i++)
        for (int j = 0; j < 16; j++)
            m[i][j] = 1e-30f * random_float(&state);
    for (int i = 0; i < 16; i++)
        x[i] = 1e-30f * random_float(&state);
    if (!dct16_forward_equal(x, m))
        return -9;

    return 0;
}

