/*
 * 2-lane float DCT-16 inverse transform.
 * Inverse uses m[i][j] access (row i, varying j).  Two adjacent output rows
 * (i, i+1) need m[i][j] and m[i+1][j] which are NOT in adjacent memory (they
 * are 64 bytes apart).  We assemble the 2-lane vector from two scalar loads
 * per j step.  The accumulation order j=0..15 is preserved per lane.
 */
static inline void xtensa_dct16_inverse(const float *x, float *y,
    const float m[16][16])
{
    int i;
    for (i = 0; i + 1 < 16; i += 2) {
        ae_f32x2 acc;
        int j;

        /* j = 0 */
        ae_f32x2 mv;
        mv.v[0] = m[i][0];
        mv.v[1] = m[i + 1][0];
        float xj0 = x[0];
        ae_f32x2 xv = { xj0, xj0 };
        acc = AE_F32X2_MULF_F32X2(xv, mv);

        for (j = 1; j < 16; j++) {
            ae_f32x2 mv2;
            mv2.v[0] = m[i][j];
            mv2.v[1] = m[i + 1][j];
            float xj = x[j];
            ae_f32x2 xv2 = { xj, xj };
            ae_f32x2 prod = AE_F32X2_MULF_F32X2(xv2, mv2);
            acc = AE_F32X2_ADDS_F32X2(acc, prod);
        }
        AE_SF32X2_I(acc, &y[i], 0);
    }
}

