321	LC3_HOT static void resample_16k_12k8(
322	    struct lc3_ltpf_hp50_state *hp50, const int16_t *x, int16_t *y, int n)
323	{
324	#ifdef LC3_RESAMPLE_16K_SIMD
325	    /* HiFi4 SIMD path: 20-tap FIR via 4-lane AE_MULAAAAQ16, scalar hp50 biquad.
326	     * Mirrors resample_x64k_12k8(4, ...) phase addressing and Q14 rounding. */
327	    const int p = 4, w = 2*(40 / p);
328	    x -= w - 1;
329	
330	    for (int i = 0; i < 5*n; i += 5) {
331	        const int16_t *hn = h_16k_12k8_q15 + (i % p) * w;
332	        const int16_t *xn = x + (i / p);
333	
334	        int32_t un = xtensa_resample_fir(xn, hn, w);
335	        int32_t yn = filter_hp50(hp50, un);
336	        *(y++) = (yn + (1 << 15)) >> 16;
337	    }
338	#else
339	    resample_x64k_12k8(4, h_16k_12k8_q15, hp50, x, y, n);
340	#endif
341	}
342	#endif /* resample_16k_12k8 */
