     - 关键代码（完整重写文件）：
     ```c
     #ifndef LC3_SNS_XTENSA_H
     #define LC3_SNS_XTENSA_H
     #include <stdint.h>
     #include <string.h>
     #if defined(TEST_XTENSA_HIFI4)
     #define LC3_SNS_XTENSA_HIFI4
     #elif defined(CONFIG_LIB_LC3_XTENSA_HIFI4) && defined(__XTENSA__)
     #include <xtensa/config/core-isa.h>
     #if XCHAL_HAVE_HIFI4
     #include <xtensa/tie/xt_hifi2.h>
     #define LC3_SNS_XTENSA_HIFI4
     #endif
     #endif
     /* Bit-exactness contract: IEEE 754 float addition NOT associative,
      * but SIMD keeps SAME j=0..15 accumulation order per lane → bit-exact.
      * Define LC3_SNS_DCT16_DISABLE to keep scalar path. */
     #if defined(LC3_SNS_XTENSA_HIFI4)
     #if !defined(LC3_SNS_DCT16_DISABLE)
     #define LC3_SNS_DCT16_SIMD 1
     static inline ae_f32x2 sns_f32x2_broadcast(float x) {
         int xi;
         memcpy(&xi, &x, sizeof(xi));
         ae_int32 i32 = (ae_int32)xi;
         ae_f32 f32 = AE_MOVF32_FROMINT32(i32);
         return AE_MOVF32X2_FROMF32(f32);
     }
     static inline ae_f32x2 sns_f32x2_pair(float a, float b) {
         float tmp[2];
         tmp[0] = a;
         tmp[1] = b;
         return AE_LF32X2_I((const ae_f32x2 *)tmp, 0);
     }
     static inline void xtensa_dct16_forward(const float *x, float *y,
         const float m[16][16]) {
         int i;
         for (i = 0; i + 1 < 16; i += 2) {
             ae_f32x2 acc;
             int j;
             ae_f32x2 mv = AE_LF32X2_I((const ae_f32x2 *)&m[0][i], 0);
             ae_f32x2 xv = sns_f32x2_broadcast(x[0]);
             acc = AE_F32X2_MULF_F32X2(xv, mv);
             for (j = 1; j < 16; j++) {
                 mv = AE_LF32X2_I((const ae_f32x2 *)&m[j][i], 0);
                 xv = sns_f32x2_broadcast(x[j]);
                 ae_f32x2 prod = AE_F32X2_MULF_F32X2(xv, mv);
                 acc = AE_F32X2_ADDS_F32X2(acc, prod);
             }
             AE_SF32X2_I(acc, (ae_f32x2 *)&y[i], 0);
         }
     }
     static inline void xtensa_dct16_inverse(const float *x, float *y,
         const float m[16][16]) {
         int i;
         for (i = 0; i + 1 < 16; i += 2) {
             ae_f32x2 acc;
             int j;
             ae_f32x2 mv = sns_f32x2_pair(m[i][0], m[i + 1][0]);
             ae_f32x2 xv = sns_f32x2_broadcast(x[0]);
             acc = AE_F32X2_MULF_F32X2(xv, mv);
             for (j = 1; j < 16; j++) {
                 mv = sns_f32x2_pair(m[i][j], m[i + 1][j]);
                 xv = sns_f32x2_broadcast(x[j]);
                 ae_f32x2 prod = AE_F32X2_MULF_F32X2(xv, mv);
                 acc = AE_F32X2_ADDS_F32X2(acc, prod);
             }
             AE_SF32X2_I(acc, (ae_f32x2 *)&y[i], 0);
         }
     }
     #endif /* LC3_SNS_DCT16_DISABLE */
     #endif /* LC3_SNS_XTENSA_HIFI4 */
     #endif /* LC3_SNS_XTENSA_H */
     ```

