#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "lc3.h"

#define DT_US 10000
#define SR_HZ 16000
#define NCH 1
#define NBYTES 40  /* typical 32kbps at 10ms: 32000*0.01/8=40 bytes */
#define NFRAMES 10

int main(void)
{
    int sr_pcm = SR_HZ;
    unsigned enc_size = lc3_encoder_size(DT_US, SR_HZ);
    void *enc_mem = malloc(enc_size);
    lc3_encoder_t enc = lc3_setup_encoder(DT_US, SR_HZ, sr_pcm, enc_mem);
    if (!enc) { fprintf(stderr, "setup failed\n"); return 2; }

    int frame_samples = DT_US * SR_HZ / 1000000;
    int16_t *pcm = malloc(frame_samples * sizeof(int16_t) * NCH);
    uint8_t out[NBYTES];

    /* deterministic pseudo-random PCM (no Date/rand dependency) */
    unsigned seed = 0x1234abcd;
    for (int f = 0; f < NFRAMES; f++) {
        for (int i = 0; i < frame_samples; i++) {
            seed = seed * 1103515245 + 12345;
            pcm[i] = (int16_t)((seed >> 16) & 0x7fff) - 16384;
        }
        int ret = lc3_encode(enc, LC3_PCM_FORMAT_S16, pcm, NCH, NBYTES, out);
        if (ret) { fprintf(stderr, "encode frame %d failed\n", f); return 3; }
        fwrite(out, 1, NBYTES, stdout);
    }
    return 0;
}
EOF

