/* ---- ae_f32x2: 2-lane single-precision float (host shim) ---- */

typedef struct {
    float v[2];
} ae_f32x2;

typedef struct {
    int32_t v[2];
} ae_int32x2;

/* host shim: ae_int32 is a plain int32 so (ae_int32)xi cast works */
typedef int32_t ae_int32;

/* host shim: ae_f32 is a plain float so arithmetic and memcpy work */
typedef float ae_f32;

/* reinterpret int32 bit pattern as f32 (host: memcpy) */
#define AE_MOVF32_FROMINT32(i32) ({ \
    int32_t ae_i_ = (i32); \
    ae_f32 ae_r_; \
    memcpy(&ae_r_, &ae_i_, 4); \
    ae_r_; \
})

/* broadcast scalar f32 to both lanes of f32x2 */
#define AE_MOVF32X2_FROMF32(f) ({ \
    ae_f32 ae_s_ = (f); \
    ae_f32x2 ae_r_; \
    ae_r_.v[0] = ae_s_; \
    ae_r_.v[1] = ae_s_; \
    ae_r_; \
})

#define AE_L32X2_I(p, off) ({ \
    const int32_t *ae_src_ = (const int32_t *)(p); \
    ae_int32x2 ae_r_; \
    ae_r_.v[0] = ae_src_[(off)]; \
    ae_r_.v[1] = ae_src_[(off) + 1]; \
    ae_r_; \
})

#define AE_S32X2_I(d, p, off) do { \
    int32_t *ae_dst_ = (int32_t *)(p); \
    ae_dst_[(off)] = (d).v[0]; \
    ae_dst_[(off) + 1] = (d).v[1]; \
} while (0)

/* reinterpret int32x2 bits as f32x2 */
#define AE_F32X2_FROM_I32X2(d) ({ \
    ae_f32x2 ae_r_; \
    uint32_t a0 = (uint32_t)(d).v[0], a1 = (uint32_t)(d).v[1]; \
    memcpy(&ae_r_.v[0], &a0, 4); \
    memcpy(&ae_r_.v[1], &a1, 4); \
    ae_r_; \
})

/* load 2 floats from address */
#define AE_LF32X2_I(p, off) ({ \
    const float *ae_src_ = (const float *)(p); \
    ae_f32x2 ae_r_; \
    ae_r_.v[0] = ae_src_[(off)]; \
